/* a human approves tools marked approval=True; pauses until s->agent.answer is set */
static void pre_ask(void *st, tlg_run_t *run)
{
    pet_watcher_state_t *s = st;
    tlg_agent_t *a = &s->agent;
    char names[38] = "";
    size_t used = 0;
    for (int i = 0; i < a->plan_len; i++) {
        const tlg_action_t *ac = &pet_watcher_domain.actions[a->plan[i]];
        if (!ac->approval) continue;
        int w = snprintf(names + used, sizeof names - used, "%s%s", used ? "+" : "", ac->name);
        if (w > 0 && (size_t)w < sizeof names - used) used += (size_t)w;
    }
    if (a->answer == TLG_ANSWER_NONE) {
        char q[48];
        snprintf(q, sizeof q, "approve %s?", names);
        tlg_agent_say(&s->agent, "waiting for a human: %s", q);
        tlg_interrupt(run, q);
        return;
    }
    if (a->answer == TLG_ANSWER_YES) {
        a->approved = true;
        tlg_agent_say(&s->agent, "human approved %s", names);
    } else {
        for (int i = 0; i < a->plan_len; i++)
            if (pet_watcher_domain.actions[a->plan[i]].approval) a->banned |= 1u << a->plan[i];
        a->approved = false;
        a->plan_len = 0;
        tlg_agent_say(&s->agent, "human said no to %s: replanning without it", names);
    }
    a->answer = TLG_ANSWER_NONE;
}

