/* prebuilt.after_verify */
static int route_verify(const void *st)
{
    const pet_watcher_state_t *s = st;
    if (s->agent.verdict == TLG_VERIFY_OK) return PET_WATCHER_NODE_ACT;
    if (s->agent.verdict == TLG_VERIFY_NEEDS_APPROVAL) return PET_WATCHER_NODE_ASK;
    return PET_WATCHER_NODE_PLAN;
}

/* prebuilt.after_ask */
static int route_ask(const void *st)
{
    const pet_watcher_state_t *s = st;
    return s->agent.approved ? PET_WATCHER_NODE_VERIFY : PET_WATCHER_NODE_PLAN;
}

